/**
 * The return value of a tool call.
 *
 * A discriminated union on `kind`, not a flat object with spare fields. Why:
 * the reply is generated by code rather than written by the LLM, i.e. a
 * `switch` function over the result — the union makes TypeScript force every
 * branch to be handled, while a flat object turns that into a chain of
 * `if (x !== undefined)`.
 */

import type {
  DoorId,
  MirrorId,
  MusicAction,
  Screen,
  TimeQuery,
  TurnSignal,
  WiperMode,
  Zone,
} from './car-state'

export type NumericField = 'temperature' | 'fanSpeed' | 'seatHeat'

/**
 * Parts that open/close. One `kind` for all six instead of six separate
 * `kind`s, because their replies differ only in **the name** — "Đã mở cốp
 * sau" ("Opened the trunk") and "Đã hạ kính trước trái" ("Lowered the
 * front-left window") are the same sentence with two different labels. The
 * verbs really do differ (mở/hạ/gập — open/lower/fold), but that's a lookup
 * table in `say.ts`, not a branch.
 */
export type OpeningPart =
  'door' | 'window' | 'mirror' | 'sunroof' | 'frunk' | 'trunk'

export type ToolResult =
  | {
      kind: 'numeric'
      field: NumericField
      /** The zones actually touched. Empty for `fanSpeed` (not per-zone). */
      zones: Zone[]
      from: number
      to: number
      /**
       * The command was stopped at the bound. State still changes up to the
       * bound — this is the trace that lets the reply say "đã ở mức thấp nhất
       * rồi" ("already at the lowest") instead of staying silent.
       */
      clamped: boolean
      /**
       * Temperature only: the command just turned the A/C on by itself because
       * it was off. Adjusting the temperature means wanting the A/C running —
       * for "bật điều hoà 20 độ" ("turn on the A/C at 20 degrees"), if the
       * model only calls `set_temperature` the car must still turn it on, and
       * the reply must say so.
       */
      acTurnedOn?: boolean
    }
  | {
      kind: 'toggle'
      feature: 'ac' | 'recirculation' | 'frontDefrost' | 'rearDefrost'
      on: boolean
      /** The state was already as requested — nothing changed. */
      alreadySet: boolean
    }
  | { kind: 'navigation'; from: Screen; to: Screen }
  | {
      kind: 'opening'
      part: OpeningPart
      /**
       * The positions actually touched. Empty for things there's only one of
       * (the sunroof, the two trunks) — `part` is enough to name them.
       */
      targets: Array<DoorId | MirrorId>
      /** Mirrors: `true` means **unfolded**, `false` means folded. Everything else: open / closed. */
      open: boolean
      /** Every touched position was already as requested — nothing changed. */
      alreadySet: boolean
    }
  | { kind: 'turnSignal'; from: TurnSignal; to: TurnSignal }
  | { kind: 'wipers'; from: WiperMode; to: WiperMode }
  | {
      kind: 'time'
      what: TimeQuery
      /**
       * The clock is read when the **command runs**, not when a `ToolResult`
       * is built somewhere else — same reason `runCommand` takes state and not
       * just actions.
       *
       * This is the only branch that makes `describeResult` less than pure:
       * the same `ToolResult` still yields the same sentence, but two
       * `tell_time` calls a minute apart are two different `ToolResult`s.
       * That's the nature of the question, not a state leak.
       */
      at: Date
    }
  | {
      kind: 'music'
      action: MusicAction
      /** The track in the player *after* the command. `null` when the queue is empty. */
      track: { title: string; artist: string } | null
      /** Nothing changed: told to play while playing, told to turn off while off… */
      alreadySet: boolean
    }
  /**
   * `play_music` found no track: YouTube had no results, or the search call
   * failed. A successful find has no `kind` of its own — it's `music` with
   * `action: 'play'`, because by the time the command returns the track is
   * already in the player.
   *
   * The previous version returned `musicSearch` as soon as the search
   * *started*, and "Đang tìm…" ("Searching…") stayed on the status bar after
   * the music was already playing. Now the command waits for the search to
   * finish.
   */
  | { kind: 'musicSearchFailed'; query: string; problem: string }
  | { kind: 'spoken'; reason: string }
  | {
      kind: 'rejected'
      /** Zod rejected the arguments, or the model called a nonexistent tool. Retried exactly once (`src/prompt/retry.ts`). */
      toolName: string
      problem: string
    }
